    const rl = $('rwList'); $('rwL').onclick = () => rl.scrollBy({ left: -rl.clientWidth * .8, behavior: 'smooth' }); $('rwR').onclick = () => rl.scrollBy({ left: rl.clientWidth * .8, behavior: 'smooth' });   // swipe the reward row (or use the arrows)
