// ===== LOOT FLIP CARDS =====
// After every cleared stage: a board of face-down cards, 30 seconds to flip ONE (boss stage: 30 cards, flip TWO).
// When you flip, every card turns over so you see what was hidden. Items are shuffled onto random cards every time.
const LOOT_TIME = 30;
const Loot = {
  el: null, timer: null, left: 0, picksLeft: 0, items: [], picked: [], got: [], cb: null,
  // ---- LOOT BY MAP + DIFFICULTY ----  Every map and every difficulty has its OWN loot table.
  //   lv = how good the loot is = map number (0 = first ... 9 = last) + difficulty shift (NORMAL +0, HARD +5, HEROIC +10) (+ a little per stage, boss boards +3).
  //   1) the rarity odds slide along ANCHORS: first NORMAL map = Common with a few Rares, HARD = good Rare / Epic gear, Legendary only on the late maps (and often on HEROIC).
  //   2) inside each rarity only a WINDOW of the item list can drop (weak items on early maps, the strongest on late ones; RAR_SPAN says where each rarity's window starts and ends),
  //      so every map drops different items with different stats.  Edit ANCHORS / RAR_SPAN / LV_SHIFT to rebalance.
  // ---- GUARDIAN SCROLL: a loot card on BOSS boards only, from Sandstorm Dunes up to the last map (never on the maps below Sandstorm Dunes, never on stage boards) ----
  SCROLL_FROM: 'dunes',   // id of the first map where the Guardian Scroll can drop
  SCROLL_CARDS: 1,        // how many Guardian Scroll cards are on each boss board there
  scrollOn(mi, boss) { const f = ADV_MAPS.findIndex(m => m.id === this.SCROLL_FROM); return !!boss && f >= 0 && mi >= f; },
  // ---- WINGS: a loot card on BOSS boards only, from Sandstorm Dunes up to the last map (same rule as the Guardian Scroll). The rarity follows the map's loot odds: Common / Rare early, Epic / Legendary on the late maps and on HARD / HEROIC ----
  WING_CARDS: 1,          // how many Wings cards are on each boss board there
  wingPick(lv, own) {     // pick one of the 4 Wings by the loot-level rarity odds (Wings you do not own yet come up more often)
    const W = this.weights(lv), L = WING_ITEMS.map(it => ({ it, w: ((W[it.rar] || 0) + .05) * (own.has(it.id) ? .4 : 1) })); let r = Math.random() * L.reduce((a, c) => a + c.w, 0);
    for (const c of L) { r -= c.w; if (r <= 0) return c.it; } return L[0].it;
  },
  // ---- NECKLACES: a loot card on EVERY boss board (never on stage boards). Which one follows the loot level (map + difficulty): the +10% Cord Pendant on the first maps, the +50% Voidwing Collar on the last maps / HEROIC; ones you do not own yet come up more often ----
  NECK_CARDS: 1,          // how many Necklace cards are on each boss board
  neckPick(lv, own) {
    const c = 1 + Math.max(0, Math.min(this.LV_MAX, lv)) / this.LV_MAX * 4, L = NECK_ITEMS.map((it, k) => ({ it, w: (Math.max(0, 1 - Math.abs(k + 1 - c) / 1.5) + .03) * (own.has(it.id) ? .4 : 1) })); let r = Math.random() * L.reduce((a, x) => a + x.w, 0);
    for (const x of L) { r -= x.w; if (r <= 0) return x.it; } return L[0].it;
  },
  // ---- GLOVES: loot cards on EVERY boss board (never on stage boards). Rarity follows the map's loot odds (Common early ... Legendary on the late maps / HARD / HEROIC); inside a rarity the weaker pairs drop on early maps and the strongest on late ones. Pairs you do not own yet come up more often ----
  GLOVE_CARDS: 2,         // how many Glove cards are on each boss board
  glovePick(lv, own, skip) {
    const W = this.weights(lv), L = [];
    this.RAR.forEach(r => {
      if (!(W[r] > .5)) return; const list = GLOVE_ITEMS.filter(i => i.rar === r).sort((a, b) => this.gloveScore(a) - this.gloveScore(b)); if (!list.length) return;
      const q = Math.max(0, Math.min(1, (lv - this.RAR_SPAN[r][0]) / (this.RAR_SPAN[r][1] - this.RAR_SPAN[r][0])));
      list.forEach((it, k) => { if (skip && skip.has(it.id)) return; const pos = list.length > 1 ? k / (list.length - 1) : .5, g = Math.exp(-Math.pow((pos - q) / .45, 2)) + .06; L.push({ it, w: W[r] * g * (own.has(it.id) ? .3 : 1.6) }); });
    });
    if (!L.length) return GLOVE_ITEMS.find(i => i.rar === 'common');
    let r = Math.random() * L.reduce((a, c) => a + c.w, 0); for (const c of L) { r -= c.w; if (r <= 0) return c.it; } return L[L.length - 1].it;
  },
  gloveScore(it) { const s = it.stats; return (s.dmg || 0) * 3 + ((s.vit || 0) + (s.dex || 0) + (s.agi || 0) + (s.luk || 0)) * 1.5; },
  RAR: ['common', 'rare', 'epic', 'legendary'],
  LV_SHIFT: [0, 5, 10], LV_MAX: 18,
  ANCHORS: [[0, [90, 10, 0, 0]], [3, [62, 34, 4, 0]], [6, [30, 50, 18, 2]], [9, [10, 42, 40, 8]], [12, [0, 25, 50, 25]], [15, [0, 12, 45, 43]], [18, [0, 5, 40, 55]]],   // [lv, [Common, Rare, Epic, Legendary] weights]
  RAR_SPAN: { common: [0, 8], rare: [1, 12], epic: [5, 16], legendary: [8, 18] },   // lv where a rarity's item window starts (weakest items) and ends (strongest items)
  lvOf(mi, diff, boss, st = 0) { return Math.min(this.LV_MAX, mi + this.LV_SHIFT[diff | 0] + (boss ? 3 : st * .4)); },
  weights(lv) {   // rarity odds at a loot level (straight line between the ANCHORS)
    const A = this.ANCHORS; lv = Math.max(0, Math.min(this.LV_MAX, lv)); let k = 0; while (k < A.length - 2 && lv > A[k + 1][0]) k++;
    const l0 = A[k][0], l1 = A[k + 1][0], t = (lv - l0) / (l1 - l0), o = {}; this.RAR.forEach((r, i) => o[r] = A[k][1][i] + (A[k + 1][1][i] - A[k][1][i]) * t); return o;
  },
  pool(lv, weapons) {   // the items that CAN drop at this loot level: [{ it, g }], g = how central the item is in its rarity window (1 = most likely)
    const W = this.weights(lv), out = [], list = weapons ? SHOP_WEAPON_ITEMS.filter(i => i.id !== 'w_titan_cannon' && i.id !== 'w_tempest_arc').concat(WEAPON_ITEMS) : ITEMS, sc = it => weapons ? ((it.stats && it.stats.dmg) || 0) : this.score(it);
    this.RAR.forEach(r => {
      if (!(W[r] > .5)) return;
      const L = list.filter(i => i.rar === r).sort((a, b) => sc(a) - sc(b)); if (!L.length) return;
      const q = Math.max(0, Math.min(1, (lv - this.RAR_SPAN[r][0]) / (this.RAR_SPAN[r][1] - this.RAR_SPAN[r][0])));
      L.forEach((it, k) => { const pos = L.length > 1 ? k / (L.length - 1) : .5, g = Math.exp(-Math.pow((pos - q) / .4, 2)); if (g >= .25) out.push({ it, g }); });
    });
    return out;
  },
  rank: { common: 0, rare: 1, epic: 2, legendary: 3 },
  score(it) { const s = it.stats || {}; return (s.dmg || 0) * 9 + (s.def || 0) * 1.5 + (s.hp || 0) * .55 + Math.max(0, s.agi || 0) * .9 + Math.min(0, s.agi || 0) * .3; },   // how good an item's stats are
  avgScore(rar) { this._avg = this._avg || {}; if (this._avg[rar] == null) { const l = ITEMS.filter(i => i.rar === rar); this._avg[rar] = l.length ? l.reduce((a, i) => a + this.score(i), 0) / l.length : 1; } return this._avg[rar] || 1; },
  chipVals(si, boss, mi) {   // chip card values: 10 / 20 / 30 / 50 / 100 on stages, bigger on boss boards; later maps pay more
    const p = si + mi * .6, base = boss ? [50, 100, 150, 200, 300, 500] : [10, 20, 30, 50, 100], w = boss ? [30, 28, 20, 12, 7, 3] : [Math.max(8, 40 - p * 2), 30, 16 + p, 10 + p, 4 + p * .5];
    let r = Math.random() * w.reduce((a, b) => a + b, 0), k = 0; for (; k < w.length - 1; k++) { r -= w[k]; if (r <= 0) break; }
    return Math.max(10, Math.round(base[k] * (1 + .25 * mi) * ADV_DIFFS[Adventure.diff | 0].chips / 10) * 10);   // HARD / HEROIC pay more chips
  },
  roll(si, boss) {   // stages: 1-2 gear cards from this map's table, the rest chips / stones. Boss board: 30 cards = 6 gear + 2 weapons + stones + chips (the best rarity this map can give is guaranteed once).
    const mi = Adventure.mi | 0, st = Adventure.si | 0, df = Adventure.diff | 0, nItems = boss ? 6 : (Math.random() < .4 ? 2 : 1), n = boss ? 30 : 9;
    const lv = this.lvOf(mi, df, boss, st), W = this.weights(lv), own = new Set((Profile.data || Profile.load()).owned.map(baseId)), out = [];
    const gear = this.pool(lv, false), wpn = boss ? this.pool(lv, true) : [];
    const pick = (sub, from) => {   // pick the rarity by the map's odds, then an item of it (items you don't own yet show up more often)
      const R = {}; sub.forEach(c => (R[c.it.rar] = R[c.it.rar] || []).push(c)); const ks = Object.keys(R); if (!ks.length) return false;
      let r = Math.random() * ks.reduce((a, k) => a + (W[k] || 0) + .001, 0), rar = ks[ks.length - 1]; for (const k of ks) { r -= (W[k] || 0) + .001; if (r <= 0) { rar = k; break; } }
      const L = R[rar], wf = c => c.g * (own.has(c.it.id) ? .25 : 1.6) + .001; let x = Math.random() * L.reduce((a, c) => a + wf(c), 0), p = L[L.length - 1]; for (const c of L) { x -= wf(c); if (x <= 0) { p = c; break; } }
      from.splice(from.indexOf(p), 1); out.push({ it: p.it }); return true;
    };
    if (boss) { const top = this.RAR.slice().reverse().find(r => W[r] >= 8); if (top) pick(gear.filter(c => c.it.rar === top), gear); }   // boss: one card of the best rarity this map can drop
    while (out.length < nItems && gear.length) pick(gear, gear);
    if (boss) for (let k = 0; k < 2 && wpn.length; k++) pick(wpn, wpn);   // BOSS KILL ONLY: 2 weapon cards (Shop or signature weapons) from the same map table
    for (let k = boss ? 3 : (Math.random() < .7 ? 1 : 0); k > 0 && out.length < n; k--) out.push(this.stoneCard(mi, boss, df));   // 1-2 stones per card: 1 stone card on most stage boards, 3 on a boss board
    if (this.scrollOn(mi, boss)) for (let k = 0; k < this.SCROLL_CARDS && out.length < n; k++) out.push({ scroll: 1, n: 1 });   // Guardian Scroll card (Sandstorm Dunes and later, boss board only)
    if (this.scrollOn(mi, boss)) for (let k = 0; k < this.WING_CARDS && out.length < n; k++) out.push({ it: this.wingPick(lv, own) });   // Wings card (Sandstorm Dunes and later, boss board only)
    if (boss) for (let k = 0; k < this.NECK_CARDS && out.length < n; k++) out.push({ it: this.neckPick(lv, own) });   // Necklace card (every boss board)
    if (boss) { const got = new Set(); for (let k = 0; k < this.GLOVE_CARDS && out.length < n; k++) { const g = this.glovePick(lv, own, got); got.add(g.id); out.push({ it: g }); } }   // Glove cards (every boss board, two different pairs)
    while (out.length < n) out.push({ chips: this.chipVals(si, boss, mi) });
    for (let i = out.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [out[i], out[j]] = [out[j], out[i]]; }   // random positions every time
    return out;
  },
  stoneCard(mi, boss, df = 0) {   // which stone: better kinds on later maps and on HARD / HEROIC (boss boards pay a bit better); 1 stone, sometimes 2
    const c = 1 + mi * .5 + df * .8 + (boss ? .8 : 0), w = [1, 2, 3, 4, 5].map(t => Math.max(0, 1 - Math.abs(t - c) / 1.6));
    let r = Math.random() * w.reduce((x, y) => x + y, 0), t = 1; for (; t < 5; t++) { r -= w[t - 1]; if (r <= 0) break; }
    return { stone: t, n: Math.random() < (boss ? .5 : .3) ? 2 : 1 };
  },
  cardHTML(e, i) {
    if (e.stone) { const s = STONE_TYPES[e.stone - 1]; return `<div class="lc" data-i="${i}" style="--rc:${s.col}"><div class="in"><div class="fr"><span>?</span></div><div class="bk"><img src="${s.img}" alt="" draggable="false"><b>+${e.n}</b><i>${s.n}</i><em></em></div></div></div>`; }
    if (e.scroll) { const m = matOf('support', 1); return `<div class="lc" data-i="${i}" style="--rc:${m.col}"><div class="in"><div class="fr"><span>?</span></div><div class="bk"><img src="${m.img}" alt="" draggable="false"><b>+${e.n}</b><i>${m.name}</i><em></em></div></div></div>`; }
    if (e.chips) return `<div class="lc" data-i="${i}" style="--rc:#ffd24a"><div class="in"><div class="fr"><span>?</span></div><div class="bk"><img src="assets/chip.png" alt="" draggable="false"><b>+${e.chips}</b><i>Chips</i><em></em></div></div></div>`;
    const it = e.it, r = RARITY[it.rar];
    return `<div class="lc" data-i="${i}" style="--rc:${r.color}"><div class="in"><div class="fr"><span>?</span></div><div class="bk">${it.img ? `<img src="${it.img}" alt="" draggable="false">` : `<u>${it.type}</u>`}<b>${it.name}</b><i>${r.name}${it.type === 'weapon' ? ' weapon' : ''}</i><em></em></div></div></div>`;
  },
  open(si, boss, cb) {
    Profile.data || Profile.load();
    this.cb = cb; this.items = this.roll(si, boss); this.picked = []; this.got = []; this.picksLeft = boss ? 2 : 1; this.left = LOOT_TIME;
    if (!this.el) { this.el = document.createElement('div'); this.el.id = 'loot'; this.el.className = 'scr'; $('app').appendChild(this.el); }
    const el = this.el, cols = boss ? 10 : 3;
    el.innerHTML = `<div class="panel lootp"><h2>${boss ? 'Boss loot' : 'Stage loot'} ${Wallet.badge()}${Stones.badge()}</h2><p id="lootMsg"></p><div class="loot-bar"><i id="lootBar"></i></div>
      <div class="loot-grid${boss ? ' big' : ''}" style="--cols:${cols}">${this.items.map((it, i) => this.cardHTML(it, i)).join('')}</div>
      <div id="lootGot"></div><div class="row"><button class="btn" id="bLootGo" hidden>Continue</button></div></div>`;
    el.hidden = false; $('over').hidden = true;
    el.querySelectorAll('.lc').forEach(c => c.onclick = () => this.pick(+c.dataset.i));
    $('bLootGo').onclick = () => this.close();
    this.msg(); clearInterval(this.timer); this.timer = setInterval(() => this.tick(), 250); this.t0 = performance.now(); this.tick();
  },
  msg() { $('lootMsg').textContent = this.picksLeft > 0 ? (this.picksLeft > 1 ? 'Flip 2 cards: items, chips or stones!' : (this.picked.length ? 'Flip your last card!' : 'Flip a card: an item, chips or stones!')) + ' The rest turn over after.' : 'Here is what was hiding on the board:'; },
  tick() {
    this.left = Math.max(0, LOOT_TIME - (performance.now() - this.t0) / 1000); const b = $('lootBar'); if (b) { b.style.width = (this.left / LOOT_TIME * 100) + '%'; b.classList.toggle('low', this.left < 8); }
    if (this.left <= 0 && this.picksLeft > 0) {   // out of time: the board flips a random card for you
      const free = this.items.map((_, i) => i).filter(i => !this.picked.includes(i));
      while (this.picksLeft > 0 && free.length) this.pick(free.splice(Math.floor(Math.random() * free.length), 1)[0], true);
    }
  },
  pick(i, auto) {
    if (this.picksLeft <= 0 || this.picked.includes(i)) return;
    const e = this.items[i], card = this.el.querySelector(`.lc[data-i="${i}"]`), D = Profile.data;
    this.picked.push(i); this.picksLeft--; card.classList.add('up', 'mine');
    if (e.stone) { Stones.add(e.n, e.stone); this.got.push({ stone: e.stone, n: e.n }); card.querySelector('em').textContent = 'Added!'; Snd.play(e.stone >= 4 ? 'win' : 'pick'); }
    else if (e.scroll) { Mats.add(matOf('support', 1), e.n); this.got.push({ scroll: 1, n: e.n }); card.querySelector('em').textContent = 'Added!'; Snd.play('win'); }
    else if (e.chips) { Wallet.add(e.chips); this.got.push({ chips: e.chips }); card.querySelector('em').textContent = 'Added!'; Snd.play(e.chips >= 100 ? 'win' : 'pick'); }
    else { const it = e.it, dup = Profile.hasBase(it.id); Profile.addCopy(it.id); Profile.save(); this.got.push({ it, dup, n: 1 }); card.querySelector('em').textContent = dup ? 'NEW ITEM (+0)' : 'NEW!'; Snd.play(it.rar === 'legendary' || it.rar === 'epic' ? 'win' : 'pick'); }
    this.msg();
    if (this.picksLeft <= 0) { clearInterval(this.timer); setTimeout(() => this.revealAll(), auto ? 300 : 800); }
  },
  revealAll() {
    const cards = [...this.el.querySelectorAll('.lc')];
    cards.forEach((c, i) => { if (!c.classList.contains('up')) setTimeout(() => { c.classList.add('up', 'rest'); }, 40 * i); });
    setTimeout(() => {
      $('lootGot').innerHTML = this.got.map(g => g.scroll ? `<div class="got" style="--rc:${matOf('support', 1).col}"><b><img class="cb" src="${matOf('support', 1).img}" alt=""> +${g.n} ${matOf('support', 1).name}</b> <small>added to your Items</small></div>` : g.stone ? `<div class="got" style="--rc:${STONE_TYPES[g.stone - 1].col}"><b><img class="cb" src="${STONE_TYPES[g.stone - 1].img}" alt=""> +${g.n} ${STONE_TYPES[g.stone - 1].n}${g.n > 1 ? 's' : ''}</b> <small>added to your stones</small></div>` : g.chips ? `<div class="got" style="--rc:#ffd24a"><b><img class="cb" src="assets/chip.png" alt=""> +${g.chips} chips</b> <small>added to your wallet</small></div>` : `<div class="got" style="--rc:${RARITY[g.it.rar].color}"><b>${g.it.name}</b> <i>${RARITY[g.it.rar].name} ${g.it.type}</i> ${Profile.statText(g.it.stats)}${g.dup ? ` <small>(new separate item, +0)</small>` : ' <small>added to your inventory</small>'}</div>`).join('');
      $('bLootGo').hidden = false; this.msg();
    }, 40 * cards.length + 500);
  },
  close() { clearInterval(this.timer); this.el.hidden = true; const cb = this.cb; this.cb = null; if (cb) cb(); },
};

